"use client"

import * as React from "react"
import {
  Check,
  ChevronRight,
  Fingerprint,
  LifeBuoy,
  MessageSquareText,
  ShieldCheck,
  type LucideIcon,
} from "lucide-react"
import { motion, useReducedMotion } from "motion/react"

import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar"
import { Button } from "@/components/ui/button"
import { cn } from "@/lib/utils"
import { useControllableState } from "@/hooks/use-controllable-state"
import {
  GridContainer,
  GridSection,
} from "@/components/ui/grid-layout/grid-layout"
import { ToggleSwitch } from "@/components/ui/toggle-switch/toggle-switch"
import { DEFAULT_LABELS, type Auth05Labels } from "./config"
import { maskEmail } from "./mask"
import {
  Auth05CodePanel,
  Auth05PasskeyPanel,
  Auth05RecoveryPanel,
} from "./panels"
import type { Auth05Method, Auth05Props } from "./types"

const ALL_METHODS: readonly Auth05Method[] = [
  "passkey",
  "totp",
  "sms",
  "recovery",
]

const METHOD_ICONS: Record<Auth05Method, LucideIcon> = {
  passkey: Fingerprint,
  totp: ShieldCheck,
  sms: MessageSquareText,
  recovery: LifeBuoy,
}

/** 方式名称、说明、标题都按 `<method>Name` 这类键从 labels 取，使用者可以逐项覆盖。 */
function methodText(labels: Auth05Labels, method: Auth05Method) {
  return {
    name: labels[`${method}Name`],
    hint: labels[`${method}Hint`],
    title: labels[`${method}Title`],
  }
}

// 服务端和水合阶段拿不到浏览器能力，快照是 null（未知）；水合完成后 React 自动换成真实值，不会产生不匹配。
const subscribeNothing = () => () => {}
const detectPasskey = (): boolean =>
  typeof window.PublicKeyCredential !== "undefined"
const unknownPasskey = (): null => null

/** 登录第二步：账号已通过第一步认证，这里再完成一次通行密钥、验证码或恢复码验证。真实认证由回调接入。 */
function Auth05({
  account,
  methods: methodsProp,
  onPasskey,
  onSendCode,
  onVerify,
  onSuccess,
  onSwitchAccount,
  helpHref,
  passkeySupported,
  codeLength = 6,
  resendSeconds = 60,
  brand,
  labels: labelsProp,
  method: methodProp,
  defaultMethod,
  onMethodChange,
  rememberDevice: rememberProp,
  defaultRememberDevice = false,
  onRememberDeviceChange,
  className,
  ...props
}: Auth05Props) {
  const labels = { ...DEFAULT_LABELS, ...labelsProp }
  const methods = React.useMemo(() => {
    const list = (methodsProp ?? ALL_METHODS).filter(
      (item, index, all) =>
        ALL_METHODS.includes(item) && all.indexOf(item) === index,
    )
    return list.length > 0 ? list : ALL_METHODS
  }, [methodsProp])
  const first: Auth05Method = methods[0] ?? "passkey"
  const [method, setMethod] = useControllableState<Auth05Method>({
    prop: methodProp,
    defaultProp: defaultMethod ?? first,
    onChange: onMethodChange,
  })
  // 当前方式不在可用列表里时退回第一项，避免出现空面板
  const active = methods.includes(method) ? method : first
  const others = methods.filter((item) => item !== active)
  const [remember, setRemember] = useControllableState<boolean>({
    prop: rememberProp,
    defaultProp: defaultRememberDevice,
    onChange: onRememberDeviceChange,
  })
  const [done, setDone] = React.useState<Auth05Method | null>(null)
  const [busy, setBusy] = React.useState(false)
  const detected = React.useSyncExternalStore(
    subscribeNothing,
    detectPasskey,
    unknownPasskey,
  )
  const supported = passkeySupported ?? detected
  const titleRef = React.useRef<HTMLHeadingElement>(null)
  const previous = React.useRef({ active, done })
  const reduced = useReducedMotion()
  const alternativesId = React.useId()
  const length = Math.max(1, Math.min(12, Math.floor(codeLength) || 6))

  // 切换方式或验证成功后把焦点交给新内容的标题，读屏和键盘用户从这里继续
  React.useEffect(() => {
    if (previous.current.active !== active || previous.current.done !== done)
      titleRef.current?.focus()
    previous.current = { active, done }
  }, [active, done])

  function complete() {
    setDone(active)
    onSuccess?.({ method: active, rememberDevice: remember })
  }

  const text = methodText(labels, active)
  const suggestedMethod = others[0]
  const initial = account.email.trim().charAt(0).toUpperCase()

  return (
    <div
      data-slot="auth-05"
      data-method={active}
      data-state={done ? "success" : "idle"}
      className={cn(
        "w-full overflow-x-clip bg-background text-foreground",
        className,
      )}
      {...props}
    >
      <GridContainer className="max-w-3xl">
        <GridSection topLine className="px-4 py-8 sm:px-6">
          {brand && (
            <div className="mb-6 flex items-center gap-2 text-sm font-medium">
              {brand.logo}
              {brand.name}
            </div>
          )}
          <h1 className="text-2xl font-semibold tracking-tight">
            {labels.title}
          </h1>
          <p className="mt-2 text-sm leading-7 text-muted-foreground">
            {labels.description}
          </p>
        </GridSection>
        {/* 账号摘要放在标题之后：先说明要做什么，再说明是哪个账号 */}
        <GridSection
          data-slot="auth-05-account"
          className="flex flex-wrap items-center gap-x-3 gap-y-1 px-4 py-3 sm:px-6"
        >
          <Avatar size="sm">
            {account.avatar && <AvatarImage src={account.avatar} alt="" />}
            <AvatarFallback>{initial}</AvatarFallback>
          </Avatar>
          <p className="min-w-44 flex-1 truncate font-mono text-sm">
            <span className="sr-only">{labels.accountLabel}：</span>
            {maskEmail(account.email)}
          </p>
          <Button
            type="button"
            size="sm"
            variant="ghost"
            className="text-muted-foreground"
            onClick={() => onSwitchAccount?.()}
          >
            {labels.accountSwitch}
          </Button>
        </GridSection>
        <GridSection
          className={cn(
            "grid",
            !done && others.length > 0 && "md:grid-cols-[minmax(0,1fr)_17rem]",
          )}
        >
          <div className="px-4 py-8 sm:px-6">
            <motion.div
              key={done ? "success" : active}
              data-slot="auth-05-panel"
              initial={false}
              animate={
                reduced
                  ? { opacity: 1, y: 0 }
                  : { opacity: [0.7, 1], y: [4, 0] }
              }
              transition={{ duration: reduced ? 0 : 0.18 }}
            >
              <h2
                ref={titleRef}
                tabIndex={-1}
                className="mb-4 flex items-center gap-2 text-lg font-medium outline-none focus-visible:underline"
              >
                {done && (
                  <Check
                    aria-hidden
                    className="size-5 rounded-full bg-primary p-1 text-primary-foreground"
                  />
                )}
                {done ? labels.success : text.title}
              </h2>
              {done ? (
                <p className="text-sm leading-7 text-muted-foreground">
                  {labels.successDescription}
                </p>
              ) : active === "passkey" ? (
                <Auth05PasskeyPanel
                  labels={labels}
                  onBusyChange={setBusy}
                  supported={supported}
                  onPasskey={onPasskey}
                  onDone={complete}
                  suggestion={
                    suggestedMethod
                      ? {
                          name: methodText(labels, suggestedMethod).name,
                          onSelect: () => setMethod(suggestedMethod),
                        }
                      : undefined
                  }
                />
              ) : active === "recovery" ? (
                <Auth05RecoveryPanel
                  labels={labels}
                  onBusyChange={setBusy}
                  onVerify={onVerify}
                  onDone={complete}
                />
              ) : (
                <Auth05CodePanel
                  labels={labels}
                  onBusyChange={setBusy}
                  kind={active}
                  length={length}
                  phone={account.phone}
                  resendSeconds={resendSeconds}
                  onSendCode={onSendCode}
                  onVerify={onVerify}
                  onDone={complete}
                />
              )}
            </motion.div>
          </div>
          {!done && others.length > 0 && (
            // 右栏用虚线与主面板分开；窄屏变成面板下方的一块，用上边的虚线分隔
            <nav
              data-slot="auth-05-alternatives"
              aria-labelledby={alternativesId}
              className="border-t border-dashed border-edge px-4 py-6 sm:px-6 md:border-t-0 md:border-l md:px-4 md:py-8"
            >
              <h2
                id={alternativesId}
                className="mb-3 text-xs font-medium text-muted-foreground"
              >
                {labels.alternatives}
              </h2>
              <ul className="space-y-1.5">
                {others.map((item) => {
                  const Icon = METHOD_ICONS[item]
                  const info = methodText(labels, item)
                  return (
                    <li key={item}>
                      <button
                        type="button"
                        data-method={item}
                        disabled={busy}
                        onClick={() => setMethod(item)}
                        className="group/alt flex min-h-12 w-full items-center gap-3 rounded-lg border border-edge bg-background px-3 py-2 text-start transition-colors outline-none hover:bg-muted/60 focus-visible:ring-3 focus-visible:ring-ring/50 disabled:cursor-not-allowed disabled:opacity-50 pointer-coarse:min-h-14"
                      >
                        <Icon
                          aria-hidden
                          className="size-4 shrink-0 text-muted-foreground"
                        />
                        <span className="min-w-0 flex-1">
                          <span className="block truncate text-sm font-medium">
                            {info.name}
                          </span>
                          <span className="block truncate text-xs text-muted-foreground">
                            {info.hint}
                          </span>
                        </span>
                        <ChevronRight
                          aria-hidden
                          className="size-4 shrink-0 text-muted-foreground transition-transform group-hover/alt:translate-x-0.5 motion-reduce:transition-none"
                        />
                      </button>
                    </li>
                  )
                })}
              </ul>
            </nav>
          )}
        </GridSection>
        {!done && (
          <GridSection className="flex flex-col gap-3 px-4 py-4 sm:flex-row sm:items-center sm:justify-between sm:px-6">
            <div className="sm:w-72">
              <ToggleSwitch
                label={labels.rememberDevice}
                checked={remember}
                onCheckedChange={setRemember}
              />
            </div>
            {helpHref && (
              <a
                href={helpHref}
                className="text-sm text-muted-foreground underline underline-offset-4 outline-none hover:text-foreground focus-visible:ring-3 focus-visible:ring-ring/50"
              >
                {labels.help}
              </a>
            )}
          </GridSection>
        )}
      </GridContainer>
      {/* 成功是整块内容被替换，单独用一个常驻的播报区，读屏才会读出来 */}
      <p className="sr-only" aria-live="polite">
        {done ? labels.successAnnounce : ""}
      </p>
    </div>
  )
}

export { Auth05 }
export type { Auth05Account, Auth05Method, Auth05Props } from "./types"
export type { Auth05Labels } from "./config"

"use client"

import * as React from "react"

type UseControllableStateParams<T> = {
  /** 受控值；传入后组件不再维护内部状态 */
  prop?: T
  /** 非受控时的初始值 */
  defaultProp: T
  /** 值变化时回调（受控与非受控都会触发） */
  onChange?: (value: T) => void
}

/**
 * 同时支持受控与非受控的状态 hook。
 * 约定见 component-conventions 技能第 4 节：open/defaultOpen/onOpenChange 等成对 props 都用它实现。
 */
function useControllableState<T>({
  prop,
  defaultProp,
  onChange,
}: UseControllableStateParams<T>) {
  const [uncontrolled, setUncontrolled] = React.useState(defaultProp)
  const isControlled = prop !== undefined
  const value = isControlled ? prop : uncontrolled

  // 用 ref 保存最新的回调和值，保证 setValue 引用稳定
  const onChangeRef = React.useRef(onChange)
  const valueRef = React.useRef(value)
  React.useEffect(() => {
    onChangeRef.current = onChange
    valueRef.current = value
  })

  const setValue = React.useCallback(
    (next: React.SetStateAction<T>) => {
      const resolved =
        typeof next === "function"
          ? (next as (prev: T) => T)(valueRef.current)
          : next
      if (Object.is(resolved, valueRef.current)) return
      valueRef.current = resolved
      if (!isControlled) setUncontrolled(resolved)
      onChangeRef.current?.(resolved)
    },
    [isControlled],
  )

  return [value, setValue] as const
}

export { useControllableState }

"use client"

import { useRouter } from "next/navigation"

import { Auth05 } from "@/components/auth-05/auth-05"

/**
 * 登录第二步：账号已通过第一步认证后进入这里。
 * 把下面的回调换成自己的认证服务；通行密钥的 WebAuthn 调用写在 onPasskey 里，
 * challenge 必须从服务端获取，不要在客户端生成。
 */
export default function VerifyPage() {
  const router = useRouter()
  return (
    <main className="flex min-h-screen flex-col justify-center bg-background py-8 text-foreground">
      <Auth05
        account={{ email: "name@example.com", phone: "13800138000" }}
        helpHref="/support"
        onPasskey={async () => {
          throw new Error("请接入通行密钥验证")
        }}
        onSendCode={async () => {
          throw new Error("请接入短信发送接口")
        }}
        onVerify={async () => {
          throw new Error("请接入验证码校验接口")
        }}
        onSuccess={() => router.push("/")}
        onSwitchAccount={() => router.push("/login")}
      />
    </main>
  )
}

import type * as React from "react"
import type { Auth05Labels } from "./config"

type Auth05Method = "passkey" | "totp" | "sms" | "recovery"

type Auth05Account = {
  /** 邮箱，组件会脱敏后显示。 */
  email: string
  /** 头像图片；没有时显示邮箱首字母。 */
  avatar?: string
  /** 短信验证用的手机号（11 位数字），组件会脱敏后显示。 */
  phone?: string
}

type Auth05Props = Omit<React.ComponentProps<"div">, "onSuccess"> & {
  /** 已通过第一步认证的账号。 */
  account: Auth05Account
  /** 可用的验证方式，顺序即「其他验证方式」列表的顺序。@default ["passkey","totp","sms","recovery"] */
  methods?: readonly Auth05Method[]
  /**
   * 通行密钥验证。在这里调用 WebAuthn；失败时抛出 Error。
   * `name` 为 `NotAllowedError` 的错误会被当作「已取消」，其他错误显示 `message`。
   */
  onPasskey?: () => Promise<void>
  /** 发送短信验证码，失败时抛出 Error。 */
  onSendCode?: () => Promise<void>
  /** 验证验证码或恢复码，失败时抛出 Error。 */
  onVerify?: (values: {
    method: Exclude<Auth05Method, "passkey">
    code: string
  }) => Promise<void>
  /** 验证成功后的通知。 */
  onSuccess?: (values: {
    method: Auth05Method
    rememberDevice: boolean
  }) => void
  /** 点击「切换账号」。 */
  onSwitchAccount?: () => void
  /** 「联系管理员」链接地址；不传时不显示这个入口。 */
  helpHref?: string
  /** 覆盖浏览器能力检测，方便演示和测试；不传时在挂载后检测 `PublicKeyCredential`。 */
  passkeySupported?: boolean
  /** 验证码位数。@default 6 */
  codeLength?: number
  /** 短信重发间隔秒数。@default 60 */
  resendSeconds?: number
  /** 品牌名称和标志。 */
  brand?: { name: string; logo?: React.ReactNode }
  /** 覆盖默认中文文案。 */
  labels?: Partial<Auth05Labels>
  /** 受控的当前验证方式。 */
  method?: Auth05Method
  /** 初始验证方式。@default 第一个可用方式 */
  defaultMethod?: Auth05Method
  /** 验证方式变化通知。 */
  onMethodChange?: (method: Auth05Method) => void
  /** 受控的「记住此设备」。 */
  rememberDevice?: boolean
  /** 初始的「记住此设备」。@default false */
  defaultRememberDevice?: boolean
  onRememberDeviceChange?: (value: boolean) => void
}

export type { Auth05Account, Auth05Method, Auth05Props }

/** 邮箱脱敏：保留前 3 位，如 lin***@example.com；不足 3 位时只保留首位。 */
function maskEmail(email: string) {
  const at = email.lastIndexOf("@")
  if (at < 1) return email
  const name = email.slice(0, at)
  const keep = name.length > 3 ? 3 : 1
  return `${name.slice(0, keep)}***${email.slice(at)}`
}

/** 手机号脱敏：138 **** 8000。 */
function maskPhone(phone: string) {
  const digits = phone.replace(/\D/g, "")
  if (digits.length !== 11) return phone
  return `${digits.slice(0, 3)} **** ${digits.slice(7)}`
}

/** 恢复码整理：去掉非字母数字、转大写、最多 8 位，第 4 位后自动加短横线。 */
function formatRecoveryCode(raw: string) {
  const clean = raw
    .replace(/[^a-zA-Z0-9]/g, "")
    .toUpperCase()
    .slice(0, 8)
  return clean.length > 4 ? `${clean.slice(0, 4)}-${clean.slice(4)}` : clean
}

export { formatRecoveryCode, maskEmail, maskPhone }

"use client"
import * as React from "react"
/** 用同步锁拦截自动提交与回车的重复请求。 */
function useAsyncAction(fallback: string) {
  const lock = React.useRef(false)
  const [pending, setPending] = React.useState(false)
  const [error, setError] = React.useState("")
  async function run(action: () => Promise<void>) {
    if (lock.current) return false
    lock.current = true
    setPending(true)
    setError("")
    try {
      await action()
      return true
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : fallback)
      return false
    } finally {
      lock.current = false
      setPending(false)
    }
  }
  return { pending, error, setError, run }
}
export { useAsyncAction }

"use client"

import {
  InputOTP,
  InputOTPGroup,
  InputOTPSlot,
} from "@/components/ui/input-otp"

/** 6 位数字验证码输入；写法与 auth-03 保持一致：整串粘贴、满位自动提交、错误态同步到每个格子。 */
function Auth05CodeInput({
  length,
  value,
  error,
  describedBy,
  label,
  disabled,
  onChange,
  onComplete,
}: {
  length: number
  value: string
  error: boolean
  describedBy?: string
  label: string
  disabled: boolean
  onChange: (value: string) => void
  onComplete: (value: string) => void
}) {
  return (
    <div data-slot="auth-05-code-input">
      <InputOTP
        maxLength={length}
        value={value}
        onChange={onChange}
        onComplete={onComplete}
        pattern="^[0-9]*$"
        autoComplete="one-time-code"
        inputMode="numeric"
        aria-label={label}
        aria-invalid={error || undefined}
        aria-describedby={describedBy}
        disabled={disabled}
        containerClassName="w-full"
      >
        <InputOTPGroup className="w-full">
          {Array.from({ length }, (_, index) => (
            <InputOTPSlot
              key={index}
              index={index}
              aria-invalid={error || undefined}
              className="h-9 min-w-0 flex-1 border-edge text-base data-[active=true]:border-foreground/25 data-[active=true]:bg-muted/40 data-[active=true]:ring-0 pointer-coarse:h-11"
            />
          ))}
        </InputOTPGroup>
      </InputOTP>
    </div>
  )
}

export { Auth05CodeInput }

"use client"

import * as React from "react"
import { Loader2 } from "lucide-react"

import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { formatLabel, type Auth05Labels } from "./config"
import { Auth05CodeInput } from "./form-parts"
import { formatRecoveryCode, maskPhone } from "./mask"
import type { Auth05Props } from "./types"
import { useAsyncAction } from "./use-auth-form"

type PanelBase = {
  labels: Auth05Labels
  /** 请求进行中时通知父级，用于锁定「其他验证方式」，避免结果落在已卸载的面板上。 */
  onBusyChange: (busy: boolean) => void
}

function useBusy(busy: boolean, onBusyChange: (busy: boolean) => void) {
  React.useEffect(() => {
    onBusyChange(busy)
    return () => onBusyChange(false)
  }, [busy, onBusyChange])
}

type PasskeyStatus = "idle" | "waiting" | "cancelled" | "error"

/** 通行密钥：WebAuthn 由接入方在 onPasskey 里实现，这里只按回调结果显示状态。 */
function Auth05PasskeyPanel({
  labels,
  onBusyChange,
  supported,
  onPasskey,
  onDone,
  suggestion,
}: PanelBase & {
  /** `null` 表示尚未检测（服务端渲染和水合期间）。 */
  supported: boolean | null
  onPasskey?: () => Promise<void>
  onDone: () => void
  suggestion?: { name: string; onSelect: () => void }
}) {
  const [status, setStatus] = React.useState<PasskeyStatus>("idle")
  const [message, setMessage] = React.useState("")
  const lock = React.useRef(false)
  // 忙状态在事件里同步通知父级（不经过 effect），列表在同一次渲染里就被锁住；卸载时兜底解锁
  React.useEffect(() => () => onBusyChange(false), [onBusyChange])

  async function start() {
    if (lock.current || supported === false) return
    lock.current = true
    onBusyChange(true)
    setStatus("waiting")
    setMessage("")
    try {
      if (!onPasskey) throw new Error(labels.failed)
      await onPasskey()
      onDone()
    } catch (caught) {
      // 用户关闭系统弹窗、超时或拒绝时，WebAuthn 统一抛 NotAllowedError，不算故障。
      if ((caught as { name?: string } | null)?.name === "NotAllowedError") {
        setStatus("cancelled")
      } else {
        setStatus("error")
        setMessage(caught instanceof Error ? caught.message : labels.failed)
      }
    } finally {
      lock.current = false
      onBusyChange(false)
    }
  }

  const waiting = status === "waiting"
  // 状态文字放在始终存在的 aria-live 容器里，变化时才会被播报
  const liveText =
    supported === false
      ? labels.passkeyUnsupported
      : waiting
        ? labels.passkeyWaiting
        : status === "cancelled"
          ? labels.passkeyCancelled
          : ""

  return (
    <div data-slot="auth-05-passkey" data-status={status} className="space-y-4">
      <p className="text-sm leading-7 text-muted-foreground">
        {labels.passkeyDescription}
      </p>
      <p
        aria-live="polite"
        data-slot="auth-05-passkey-status"
        className="min-h-5 text-sm text-muted-foreground"
      >
        {liveText}
      </p>
      {status === "error" && message && (
        <p role="alert" className="text-xs text-destructive">
          {message}
        </p>
      )}
      <Button
        type="button"
        size="lg"
        className="w-full"
        disabled={waiting || supported === false}
        aria-busy={waiting || undefined}
        onClick={() => void start()}
      >
        {waiting ? (
          <>
            <Loader2
              aria-hidden
              className="animate-spin motion-reduce:animate-none"
            />
            {labels.passkeyWaitingButton}
          </>
        ) : (
          labels.passkeyAction
        )}
      </Button>
      {supported === false && suggestion && (
        <Button
          type="button"
          size="lg"
          variant="outline"
          className="w-full"
          onClick={suggestion.onSelect}
        >
          {formatLabel(labels.passkeySuggest, { method: suggestion.name })}
        </Button>
      )}
    </div>
  )
}

/** 验证器 App（totp）与短信共用：6 位数字，满位自动提交；短信多一步「发送」和倒计时。 */
function Auth05CodePanel({
  labels,
  onBusyChange,
  kind,
  length,
  phone,
  resendSeconds,
  onSendCode,
  onVerify,
  onDone,
}: PanelBase & {
  kind: "totp" | "sms"
  length: number
  phone?: string
  resendSeconds: number
  onSendCode?: () => Promise<void>
  onVerify?: Auth05Props["onVerify"]
  onDone: () => void
}) {
  const id = React.useId()
  const [code, setCode] = React.useState("")
  const [sent, setSent] = React.useState(false)
  const [deadline, setDeadline] = React.useState(0)
  const [remaining, setRemaining] = React.useState(0)
  const sending = useAsyncAction(labels.failed)
  const verifying = useAsyncAction(labels.failed)
  const pending = sending.pending || verifying.pending
  useBusy(pending, onBusyChange)
  const masked = phone ? maskPhone(phone) : ""

  React.useEffect(() => {
    if (!deadline) return
    const tick = () =>
      setRemaining(Math.max(0, Math.ceil((deadline - Date.now()) / 1000)))
    tick()
    const timer = window.setInterval(tick, 250)
    return () => window.clearInterval(timer)
  }, [deadline])

  async function send() {
    if (pending || remaining > 0) return
    const ok = await sending.run(async () => {
      if (!onSendCode) throw new Error(labels.failed)
      await onSendCode()
    })
    if (!ok) return
    setSent(true)
    setCode("")
    verifying.setError("")
    const seconds = Math.max(0, resendSeconds)
    setRemaining(seconds)
    // 仅在发送成功的事件回调中读取时间，不参与服务端渲染。
    setDeadline(Date.now() + seconds * 1000)
  }

  async function verify(value: string) {
    if (pending || value.length !== length) return
    const ok = await verifying.run(async () => {
      if (!onVerify) throw new Error(labels.failed)
      await onVerify({ method: kind, code: value })
    })
    if (ok) onDone()
  }

  const showCode = kind === "totp" || sent
  const description =
    kind === "totp"
      ? formatLabel(labels.totpDescription, { length })
      : formatLabel(labels.smsDescription, { phone: masked })

  return (
    <form
      noValidate
      data-slot={`auth-05-${kind}`}
      onSubmit={(event) => {
        event.preventDefault()
        void verify(code)
      }}
      className="space-y-4"
    >
      <p className="text-sm leading-7 text-muted-foreground">{description}</p>
      {kind === "sms" && (
        <>
          <Button
            type="button"
            size="lg"
            variant={sent ? "outline" : "default"}
            className="w-full"
            disabled={pending || remaining > 0}
            onClick={() => void send()}
          >
            {sending.pending
              ? labels.smsSending
              : remaining > 0
                ? formatLabel(labels.smsCountdown, { seconds: remaining })
                : sent
                  ? labels.smsResend
                  : labels.smsSend}
          </Button>
          <p
            aria-live="polite"
            className="min-h-5 font-mono text-xs text-muted-foreground"
          >
            {sent ? formatLabel(labels.smsSent, { phone: masked }) : ""}
          </p>
          {sending.error && (
            <p role="alert" className="text-xs text-destructive">
              {sending.error}
            </p>
          )}
        </>
      )}
      {showCode && (
        <>
          <div className="space-y-2">
            <Auth05CodeInput
              length={length}
              value={code}
              label={formatLabel(labels.code, { length })}
              disabled={pending}
              error={!!verifying.error}
              describedBy={verifying.error ? `${id}-error` : undefined}
              onChange={(value) => {
                setCode(value)
                verifying.setError("")
              }}
              onComplete={(value) => void verify(value)}
            />
            {verifying.error && (
              <p
                role="alert"
                id={`${id}-error`}
                className="text-xs text-destructive"
              >
                {verifying.error}
              </p>
            )}
          </div>
          <Button
            type="submit"
            size="lg"
            className="w-full"
            disabled={pending || code.length !== length}
          >
            {verifying.pending ? labels.verifying : labels.verify}
          </Button>
        </>
      )}
    </form>
  )
}

/** 恢复码：输入时自动转大写并插入短横线，格式 XXXX-XXXX。 */
function Auth05RecoveryPanel({
  labels,
  onBusyChange,
  onVerify,
  onDone,
}: PanelBase & {
  onVerify?: Auth05Props["onVerify"]
  onDone: () => void
}) {
  const id = React.useId()
  const [code, setCode] = React.useState("")
  const [localError, setLocalError] = React.useState("")
  const verifying = useAsyncAction(labels.failed)
  useBusy(verifying.pending, onBusyChange)
  const error = localError || verifying.error

  async function submit() {
    if (verifying.pending) return
    if (code.length !== 9) {
      setLocalError(labels.recoveryError)
      return
    }
    const ok = await verifying.run(async () => {
      if (!onVerify) throw new Error(labels.failed)
      await onVerify({ method: "recovery", code })
    })
    if (ok) onDone()
  }

  return (
    <form
      noValidate
      data-slot="auth-05-recovery"
      onSubmit={(event) => {
        event.preventDefault()
        void submit()
      }}
      className="space-y-4"
    >
      <p className="text-sm leading-7 text-muted-foreground">
        {labels.recoveryDescription}
      </p>
      <div className="space-y-2">
        <label
          htmlFor={`${id}-input`}
          className="text-xs text-muted-foreground"
        >
          {labels.recoveryLabel}
        </label>
        <Input
          id={`${id}-input`}
          value={code}
          onChange={(event) => {
            setCode(formatRecoveryCode(event.target.value))
            setLocalError("")
            verifying.setError("")
          }}
          placeholder={labels.recoveryPlaceholder}
          autoComplete="off"
          autoCapitalize="characters"
          autoCorrect="off"
          spellCheck={false}
          maxLength={9}
          disabled={verifying.pending}
          aria-invalid={error ? true : undefined}
          aria-describedby={`${id}-note${error ? ` ${id}-error` : ""}`}
          className="h-9 font-mono tracking-widest uppercase focus-visible:border-foreground/25 focus-visible:bg-background focus-visible:ring-0 aria-invalid:focus-visible:ring-3 pointer-coarse:h-11"
        />
        <p id={`${id}-note`} className="text-xs text-muted-foreground">
          {labels.recoveryNote}
        </p>
        {error && (
          <p
            role="alert"
            id={`${id}-error`}
            className="text-xs text-destructive"
          >
            {error}
          </p>
        )}
      </div>
      <Button
        type="submit"
        size="lg"
        className="w-full"
        disabled={verifying.pending || code.length !== 9}
      >
        {verifying.pending ? labels.verifying : labels.verify}
      </Button>
    </form>
  )
}

export { Auth05CodePanel, Auth05PasskeyPanel, Auth05RecoveryPanel }
